using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Diagnostics;using System.ComponentModel;using System.Security.Principal;using System.Collections.Generic;using CodexKit.Native;
namespace CodexKit {
internal static class NativeTaskRegistration {
    internal const string Name="CodexGuardAuto";
    static object Call(object target,string member,BindingFlags flags,params object[] args){return target.GetType().InvokeMember(member,flags,null,target,args);}
    static void Release(object target){if(target!=null&&Marshal.IsComObject(target))Marshal.FinalReleaseComObject(target);}
    internal static bool IsAccessDenied(Exception error){while(error is TargetInvocationException&&error.InnerException!=null)error=error.InnerException;return error is UnauthorizedAccessException||error is COMException&&unchecked((uint)error.HResult)==0x80070005;}
    internal static string Security(string sid){var identity=new SecurityIdentifier(sid);return "O:"+identity.Value+"D:(A;;FA;;;SY)(A;;FA;;;BA)(A;;FA;;;"+identity.Value+")";}
    internal static void Register(string executable,string sid){
        object service=null,folder=null,task=null;try{service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service",true));Call(service,"Connect",BindingFlags.InvokeMethod);folder=Call(service,"GetFolder",BindingFlags.InvokeMethod,@"\");task=Call(folder,"RegisterTask",BindingFlags.InvokeMethod,Name,NativeDesktopComponents.TaskXml(executable,sid),6,sid,null,3,Security(sid));}
        catch(Exception ex){if(IsAccessDenied(ex))throw new UnauthorizedAccessException("当前启动保护登录任务由管理员保护，需要管理员授权才能更新。",ex);throw new IOException("登录自动维护任务注册失败（0x"+unchecked((uint)ex.GetBaseException().HResult).ToString("X8")+"）："+ex.GetBaseException().Message,ex);}
        finally{Release(task);Release(folder);Release(service);}
    }
    internal static string Query(){object service=null,folder=null,task=null;try{service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service",true));Call(service,"Connect",BindingFlags.InvokeMethod);folder=Call(service,"GetFolder",BindingFlags.InvokeMethod,@"\");task=Call(folder,"GetTask",BindingFlags.InvokeMethod,Name);return Convert.ToString(Call(task,"Xml",BindingFlags.GetProperty));}catch(Exception ex){throw new IOException("启动保护任务读取失败（0x"+unchecked((uint)ex.GetBaseException().HResult).ToString("X8")+"）："+ex.GetBaseException().Message,ex);}finally{Release(task);Release(folder);Release(service);}}
    internal static ProcessStartInfo ElevationInfo(string self,string sid,string nonce){Guid id;if(!Guid.TryParseExact(nonce,"N",out id))throw new ArgumentException("授权任务标识无效。");new SecurityIdentifier(sid);return new ProcessStartInfo(self,"--register-native-guard "+sid+" "+nonce){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};}
    internal static void Elevate(string self){var nonce=Guid.NewGuid().ToString("N");var result=Path.Combine(Core.Logs,"guard-elevation-"+nonce+".json");try{Process process;try{process=Process.Start(ElevationInfo(self,Core.Sid,nonce));}catch(Win32Exception ex){if(ex.NativeErrorCode==1223)throw new OperationCanceledException("已取消管理员授权，本次启动保护未完成；其他已完成步骤保留。");throw;}using(process){if(process==null)throw new IOException("启动保护授权进程未启动。");if(!process.WaitForExit(30000))throw new IOException("授权后的任务注册仍在处理中，请稍后重新检查启动保护。");if(process.ExitCode==65)throw new IOException("管理员账户与当前账户不同，启动保护任务未修改；请使用同一账户授权。");if(process.ExitCode!=0){string message="管理员授权后仍未能注册启动保护任务。";if(File.Exists(result))message=Core.Value(Core.ReadJson(File.ReadAllText(result)),"error",message);throw new IOException(message);}}}finally{if(File.Exists(result))File.Delete(result);}}
    internal static int Complete(string expectedSid,string nonce){Guid id;if(!Guid.TryParseExact(nonce,"N",out id))return 64;if(Core.Sid!=expectedSid)return 65;if(!Core.Admin)return 66;var result=Path.Combine(Core.Logs,"guard-elevation-"+nonce+".json");try{var paths=NativePaths.Current();var executable=Path.Combine(paths.Documents,"Codex启动保护管理器","CodexInitKit.Guard.exe");NativeData.NoLinks(executable);if(!File.Exists(executable))throw new FileNotFoundException("原生启动保护程序尚未准备，任务未注册。",executable);Register(executable,Core.Sid);File.WriteAllText(result,Core.Json.Serialize(new{passed=true}));return 0;}catch(Exception ex){File.WriteAllText(result,Core.Json.Serialize(new{passed=false,error="启动保护任务注册未完成："+ex.GetBaseException().Message+"（错误码 0x"+unchecked((uint)ex.GetBaseException().HResult).ToString("X8")+"）",code="0x"+unchecked((uint)ex.GetBaseException().HResult).ToString("X8")}));return 1;}}
}
}
